import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  NetworkRefused,
  oauth2,
  object,
  router,
  secrets,
  string,
  toolAnnotations,
  withApprovals,
} from "apps";
import { mcpHealth, mcpRouter } from "apps/mcp";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";

const mcpUrl = "https://mcp.neon.tech/mcp";

/**
 * A key may only be sent to the hosts its provider listed when it was saved, so a key saved
 * before both providers listed both hosts is refused for the other one before anything is sent.
 * The check asks the other host without reading its answer and, on that refusal, the account's
 * row says to reconnect. The ask shares the check's cancellation and at most five seconds of what
 * is left of its deadline, so a slow host never fails a check whose own read passed.
 */
async function otherHostStatus(
  fetch: (input: string, init?: RequestInit) => Promise<Response>,
  {
    url,
    token,
    signal,
    deadline,
    tools,
  }: { url: string; token: string; signal: AbortSignal; deadline?: number; tools: string },
) {
  const remaining = Math.min(5_000, (deadline ?? Date.now() + 5_250) - Date.now() - 250);
  if (remaining <= 0) return undefined;
  try {
    await fetch(url, {
      method: "HEAD",
      signal: AbortSignal.any([signal, AbortSignal.timeout(Math.floor(remaining))]),
      headers: { Authorization: `Bearer ${token}` },
    });
  } catch (error) {
    // Any other failure says nothing about this key's hosts, and the check's own read passed.
    if (error instanceof NetworkRefused && error.refusal.reason === "credential_host")
      return {
        status: {
          badges: [{ label: `Reconnect to use this key for the ${tools}`, tone: "warning" as const }],
          meters: [],
          stats: [],
        },
      };
  }
  return undefined;
}

// One Neon API key serves the REST API and the MCP server, so each provider may send its credentials
// to both hosts; the REST router takes only API keys.
const neon = defineProvider({
  name: "Neon",
  hosts: ["console.neon.tech", "mcp.neon.tech"],
  auth: {
    apiKey: secrets({
      label: "API key",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
  },
  // /users/me needs a personal or organization key; project-scoped keys cannot call account-level endpoints.
  async health({ account, fetch, signal, deadline }) {
    const response = await fetch("https://console.neon.tech/api/v2/users/me", {
      signal,
      headers: { Authorization: `Bearer ${account.fields.token}` },
    });
    await decodeJson(response, object({ id: string({ minLength: 1 }) }));
    return otherHostStatus(fetch, {
      url: mcpUrl,
      token: account.fields.token,
      signal,
      deadline,
      tools: "MCP tools",
    });
  },
});

type McpAccount =
  | { method: "apiKey"; fields: { token: string } }
  | { method: "oauth"; fields: { access_token: string } };

// Neon API keys and OAuth access tokens are both sent as bearer tokens.
const mcpHeaders = (account: McpAccount) => ({
  Authorization: `Bearer ${account.method === "oauth" ? account.fields.access_token : account.fields.token}`,
});

// Neon's MCP server adds SQL execution, migrations and query tuning. It has its own OAuth
// (dynamic client registration) whose tokens only work against mcp.neon.tech; its API keys are
// ordinary Neon API keys.
const neonMcp = defineProvider({
  name: "Neon MCP",
  hosts: ["mcp.neon.tech", "console.neon.tech"],
  auth: {
    apiKey: secrets({
      label: "API key",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
    oauth: oauth2({ discover: mcpUrl }),
  },
  async health(check) {
    await mcpHealth(check, { url: mcpUrl, headers: mcpHeaders(check.account) });
    if (check.account.method === "apiKey")
      return otherHostStatus(check.fetch, {
        url: "https://console.neon.tech/api/v2/users/me",
        token: check.account.fields.token,
        signal: check.signal,
        deadline: check.deadline,
        tools: "REST API tools",
      });
    return undefined;
  },
});

export default defineApp(
  { user: { accounts: { neon: neon.many(), neonMcp: neonMcp.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      {
        api: router(
          await accountRouter(
            // A Neon API key saved for either requirement serves the REST API.
            [
              ...(user?.accounts.neon ?? []),
              ...(user?.accounts.neonMcp ?? []).filter((account) => account.method === "apiKey"),
            ],
            (account) =>
              withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
                tool.kind === "mutation" ? always() : undefined,
              ),
            { signal },
          ),
          {
            title: "Neon API",
            description:
              "Neon management REST API: projects, branches, endpoints, databases, roles, operations and organizations.",
          },
        ),
        mcp: router(
          await accountRouter(
            // The same key also serves the MCP server, beside its own OAuth sign-ins.
            [...(user?.accounts.neonMcp ?? []), ...(user?.accounts.neon ?? [])],
            async (account) =>
              withApprovals(
                await mcpRouter({ url: mcpUrl, account, headers: mcpHeaders(account), signal }),
                (tool) => (toolAnnotations(tool)?.readOnlyHint === true ? undefined : always()),
              ),
            { signal },
          ),
          {
            title: "Neon MCP",
            description:
              "Neon's remote MCP server: run SQL and transactions, inspect and migrate schemas, compare branches and tune slow queries.",
          },
        ),
      },
      {
        title: "Neon",
        description:
          "Manage Neon serverless Postgres: projects, branches, endpoints, databases, roles, operations and organizations (api), plus SQL execution, migrations and query tuning through Neon's MCP server (mcp).",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// Cookie schemes in the spec are for the console UI; API keys use bearer auth.
export const options = {
  source: { url: "https://neon.com/api_spec/release/v2.json" },
  allowedOrigin: "https://console.neon.tech",
  securitySchemes: { BearerAuth: { type: "http", scheme: "bearer" } },
  fallbackSecurity: [{ BearerAuth: [] }],
  methods: { apiKey: [{ scheme: "BearerAuth", field: "token", part: "value", prefix: "" }] },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

